import { FAQ_ITEMS } from "@/lib/faq-content";
import { TERMS_SECTIONS } from "@/lib/terms-content";
import type { AssistantRoute } from "@/lib/ai-assistant-routing";

/**
 * Deterministic store-policy answers for the AI shopping assistant.
 *
 * Session 94: shipping/policy answers are assembled from the same official
 * modules that power /faq and /terms (owner-approved wording). They are NOT
 * generated by the model, so the assistant can no longer invent a delivery
 * window, a shipping price, a return deadline, or a destination.
 */

function sectionItems(id: string): string[] {
  return TERMS_SECTIONS.find((section) => section.id === id)?.items ?? [];
}

function toBullets(items: string[]): string {
  return items.map((item) => `• ${item}`).join("\n");
}

export function buildOfficialStorePolicyText(): string {
  const shipping = sectionItems("shipping");
  const returns = sectionItems("returns");
  const payment = sectionItems("payment");
  const faqHighlights = FAQ_ITEMS.filter((f) =>
    ["delivery-time", "track-order", "return-policy", "return-process", "defective-product", "payment-methods", "how-to-login", "how-to-use-coupon"].includes(f.id)
  )
    .map((f) => `- ${f.question}: ${f.answer.replace(/\n/g, " ")}`)
    .join("\n");

  return [
    "قوانین رسمی و مصوب مارلو شاپ (از faq-content و terms-content):",
    shipping.length ? `ارسال و تحویل:\n- ${shipping.join("\n- ")}` : "",
    returns.length ? `مرجوعی و بازگشت کالا:\n- ${returns.join("\n- ")}` : "",
    payment.length ? `روش‌های پرداخت:\n- ${payment.join("\n- ")}` : "",
    `پرسش‌های پرتکرار مصوب:\n${faqHighlights}`,
  ]
    .filter(Boolean)
    .join("\n\n");
}

export const MARLOO_DOMAIN_KNOWLEDGE = `
اطلاعات قطعی مارلو شاپ:
- مارلو شاپ یک فروشگاه اینترنتی فارسی و راست‌به‌چپ است.
- صفحه اصلی: / ، کاتالوگ محصولات: /products ، سبد خرید: /cart ، ورود: /login ، ثبت‌نام: /register ، سوالات متداول: /faq ، قوانین و مقررات: /terms.
- ورود و ثبت‌نام با شماره موبایل و رمز عبور یا کد یک‌بارمصرف (OTP) انجام می‌شود.
- مشتری می‌تواند پروفایل (/profile)، سفارش‌ها (/orders)، علاقه‌مندی‌ها (/wishlist)، کدهای تخفیف (/coupons)، اعلان‌ها (/notifications) و پشتیبانی سفارش‌محور (/support) را مدیریت کند.
- ظاهر فروشگاه دو حالت روشن و تاریک دارد. حالت پیش‌فرض تاریک است و کاربر می‌تواند با دکمه ماه/خورشید در هدر بین آن‌ها جابه‌جا شود؛ انتخاب در مرورگر ذخیره می‌شود.
- درباره زمان ارسال، هزینه ارسال، مقصدها، مرجوعی و پرداخت فقط از «قوانین رسمی» زیر استفاده کن؛ هر عدد یا شرطی که در آن نیامده را از خودت نساز.

${buildOfficialStorePolicyText()}
`;

export function buildProfessionalRouteReply(route: AssistantRoute, query: string): string {
  const q = query.trim();
  if (route === "shipping") {
    const items = sectionItems("shipping");
    if (items.length === 0) {
      return "📦 اطلاعات دقیق زمان و هزینه ارسال در حال حاضر در دسترس نیست. لطفاً برای شرایط ارسال به صفحه «قوانین و مقررات» مراجعه کنید یا با پشتیبانی تماس بگیرید.";
    }
    return [
      "🚚 **ارسال و تحویل سفارش در مارلو شاپ:**",
      toBullets(items),
      "",
      "این اطلاعات از قوانین رسمی فروشگاه است؛ جزئیات نهایی هزینه و زمان دقیق بر اساس مقصد، هنگام تکمیل سفارش نمایش داده می‌شود.",
    ].join("\n");
  }

  if (route === "policy") {
    const items = sectionItems("returns");
    if (items.length === 0) {
      return "🔄 اطلاعات دقیق شرایط مرجوعی در حال حاضر در دسترس نیست. لطفاً به صفحه «قوانین و مقررات» مراجعه کنید یا با پشتیبانی تماس بگیرید.";
    }
    return ["🔄 **شرایط بازگشت و مرجوعی کالا در مارلو شاپ:**", toBullets(items)].join("\n");
  }

  if (route === "account") {
    if (/ورود|وارد|لاگین|ثبت.?نام|رمز/.test(q)) {
      return "🔐 **ورود و حساب کاربری در مارلو شاپ:**\n• برای ورود یا ثبت‌نام، کافی است با **شماره موبایل و رمز عبور** یا **کد تأیید یک‌بارمصرف (پیامکی)** اقدام کنید.\n• اگر رمز عبورتان را فراموش کرده‌اید، در صفحه ورود گزینه **«رمز عبور را فراموش کرده‌اید؟»** را بزنید تا با شماره موبایل بازیابی شود.\n• پس از ورود، از بخش **پروفایل** می‌توانید اطلاعات حساب، آدرس‌ها و سفارش‌های خود را مدیریت کنید.";
    }
    return "👤 **مدیریت حساب کاربری و خدمات مارلو شاپ:**\n• از بخش **پروفایل و حساب کاربری** می‌توانید اطلاعات شخصی و آدرس‌های خود را ویرایش کنید.\n• برای مشاهده وضعیت خریدها به **سفارش‌ها**، برای کالاهای ذخیره‌شده به **علاقه‌مندی‌ها** و برای گفتگو با کارشناسان به **پشتیبانی** مراجعه کنید.";
  }

  return "🧭 **راهنمای بخش‌های اصلی مارلو شاپ:**\n• برای مشاهده و فیلتر کالاها به بخش **محصولات** (`/products`) بروید.\n• برای پیگیری خریدهای قبلی وارد **سفارش‌ها** (`/orders`) شوید و برای مدیریت اطلاعات حساب به **پروفایل** (`/profile`) سر بزنید.";
}
